      if (_isOverdrive) {
        _ctx.shadowColor = colors.ringColor;
        _ctx.shadowBlur = 8;
      }

      _ctx.fill();
    }
    _ctx.restore();
  }
}

function _hexToRgb(hex) {
  const sanitized = hex.replace('#', '');
  const bigint = parseInt(sanitized, 16);
  return {
    r: Math.min(255, (bigint >> 16) & 255),
    g: Math.min(255, (bigint >> 8) & 255),
    b: Math.min(255, bigint & 255)
  };
}

