  gap: var(--space-4);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
}

.header-status-indicator {
  width: 8px;
  height: 8px;
  border-radius: var(--border-radius-full);
  background-color: var(--color-accent-success);
  box-shadow: var(--glow-success);
}

/* ============================================================
   ÁREA DE CONTENIDO PRINCIPAL (FLEX ROW)
   ============================================================ */
#app-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: row;
  overflow: hidden;
  min-height: 0;
}

/* ============================================================
   PANELES LATERALES DE KPI
   ============================================================ */
#panel-left,
#panel-right {
  position: relative;
  z-index: var(--z-ui-panels);
  width: var(--panel-width-left);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-4);
  background: var(--color-bg-panel);
  backdrop-filter: var(--blur-panel);
  -webkit-backdrop-filter: var(--blur-panel);
  border-color: var(--border-color-default);
  border-style: solid;
  border-width: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: var(--border-color-default) transparent;
}

#panel-left {
  border-right-width: var(--border-width-thin);
}

#panel-right {
  width: var(--panel-width-right);
  border-left-width: var(--border-width-thin);
}

#panel-left::-webkit-scrollbar,
#panel-right::-webkit-scrollbar {
  width: 4px;
}

#panel-left::-webkit-scrollbar-track,
#panel-right::-webkit-scrollbar-track {
  background: transparent;
}

#panel-left::-webkit-scrollbar-thumb,
#panel-right::-webkit-scrollbar-thumb {
  background-color: var(--border-color-default);
  border-radius: var(--border-radius-sm);
}

/* ============================================================
   ÁREA CENTRAL DEL CANVAS
   ============================================================ */
#canvas-area {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

/* Canvas superpuestos en el área central */
#canvas-area canvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

#particleCanvas {
  z-index: var(--z-canvas-particles);
  pointer-events: none;
}

#connectionCanvas {
  z-index: var(--z-canvas-connections);
  pointer-events: none;
}

#coreCanvas {
  z-index: var(--z-canvas-core);
  pointer-events: none;
}

/* ============================================================
   CAPA DE NODOS UI (SOBRE EL CANVAS)
   ============================================================ */
#nodes-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: var(--z-ui-nodes);
  pointer-events: none;
}

/* Los nodos individuales sí reciben eventos */
.node-element {
  position: absolute;
  pointer-events: all;
  transform: translate(-50%, -50%);
}

/* ============================================================
   BARRA INFERIOR DORA
   ============================================================ */
#dora-bar {
  position: relative;
  z-index: var(--z-ui-dora-bar);
  width: 100%;
  height: var(--dora-bar-height);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  padding: 0 var(--space-6);
  background: var(--color-bg-panel);
  backdrop-filter: var(--blur-panel);
  -webkit-backdrop-filter: var(--blur-panel);
  border-top: var(--border-width-thin) solid var(--border-color-default);
  gap: var(--space-8);
  overflow: hidden;
}

/* ============================================================
   OVERLAY DE OVERDRIVE
   ============================================================ */
#overdrive-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: var(--z-overdrive-overlay);
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--transition-overdrive);
}

#overdrive-overlay.active {
  opacity: 1;
  pointer-events: all;
}

