/* ==========================================================================
   styles/overdrive.css
   Tema visual completo para el modo Overdrive
   Se activa exclusivamente mediante la clase .overdrive-active en <body>
   ========================================================================== */


/* ==========================================================================
   SECCIÓN 1 - OVERRIDE DE CSS CUSTOM PROPERTIES
   ========================================================================== */

.overdrive-active {
  --color-primary: #00FFFF;
  --color-secondary: #FF00FF;
  --color-accent: #CCFF00;
  --color-bg-base: #000A0A;
  --color-bg-panel: rgba(0, 20, 20, 0.92);
  --color-text-primary: #E0FFFF;
  --color-glow-intensity: 2.5;
  --border-neon: 1px solid #00FFFF;
  --transition-speed: 0.15s;
}


/* ==========================================================================
   SECCIÓN 2 - OVERLAY PRINCIPAL
   ========================================================================== */

.overdrive-active #overdrive-overlay {
  position: fixed;
  inset: 0;
  z-index: 900;
  pointer-events: none;
  background: radial-gradient(
    ellipse at center,
    rgba(0, 255, 255, 0.04) 0%,
    transparent 70%
  );
  animation: overdrivePulse 3s ease-in-out infinite;
}

.overdrive-active #overdrive-overlay::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0, 255, 255, 0.03) 0px,
    rgba(0, 255, 255, 0.03) 1px,
    transparent 1px,
    transparent 4px
  );
  animation: scanlineScroll 0.1s linear infinite;
}

@keyframes scanlineScroll {
  from {
    background-position: 0 0;
  }
  to {
    background-position: 0 4px;
  }
}


/* ==========================================================================
   SECCIÓN 3 - EFECTOS NEÓN SOBRE NODOS Y NÚCLEO
   ========================================================================== */

.overdrive-active .node-wrapper {
  filter: drop-shadow(0 0 8px var(--color-primary)) drop-shadow(0 0 20px var(--color-primary));
  transition: filter var(--transition-speed) ease;
}

.overdrive-active .node-wrapper:nth-child(1) {
  animation: nodeNeonFlicker 2.4s ease-in-out infinite;
  animation-delay: 0s;
}

.overdrive-active .node-wrapper:nth-child(2) {
  animation: nodeNeonFlicker 2.4s ease-in-out infinite;
  animation-delay: 0.3s;
}

.overdrive-active .node-wrapper:nth-child(3) {
  animation: nodeNeonFlicker 2.4s ease-in-out infinite;
  animation-delay: 0.7s;
}

.overdrive-active .node-wrapper:nth-child(4) {
  animation: nodeNeonFlicker 2.4s ease-in-out infinite;
  animation-delay: 1.1s;
}

.overdrive-active .node-wrapper:nth-child(5) {
  animation: nodeNeonFlicker 2.4s ease-in-out infinite;
  animation-delay: 1.8s;
}

.overdrive-active .node-label {
  color: var(--color-primary);
  text-shadow:
    0 0 6px var(--color-primary),
    0 0 12px var(--color-primary);
  letter-spacing: 0.08em;
  font-weight: 700;
}

.overdrive-active #core-container {
  filter:
    drop-shadow(0 0 15px var(--color-primary))
    drop-shadow(0 0 40px rgba(0, 255, 255, 0.5));
}


/* ==========================================================================
   SECCIÓN 4 - ANIMACIONES DE TEXTO Y KPI PANELS EN MODO OVERDRIVE
   ========================================================================== */

.overdrive-active .kpi-panel {
  background: var(--color-bg-panel);
  border: var(--border-neon);
  box-shadow:
    0 0 10px rgba(0, 255, 255, 0.3),
    inset 0 0 20px rgba(0, 255, 255, 0.05);
}

.overdrive-active .kpi-value {
  color: var(--color-primary);
  text-shadow: 0 0 8px var(--color-primary);
  animation: kpiValuePulse 1.8s ease-in-out infinite;
}

.overdrive-active .kpi-label {
  color: var(--color-text-primary);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.75em;
  opacity: 0.85;
}

.overdrive-active .kpi-panel-title {
  color: var(--color-primary);
  text-shadow: 0 0 6px var(--color-primary);
  letter-spacing: 0.1em;
  font-weight: 700;
  text-transform: uppercase;
}

@keyframes kpiValuePulse {
  0%, 100% {
    text-shadow: 0 0 8px var(--color-primary);
    opacity: 1;
  }
  50% {
    text-shadow:
      0 0 12px var(--color-primary),
      0 0 24px var(--color-primary);
    opacity: 0.9;
  }
}


/* ==========================================================================
   SECCIÓN 5 - EFECTOS DE BORDE Y SCANLINE
   ========================================================================== */

.overdrive-active .kpi-panel::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border: var(--border-neon);
  border-radius: inherit;
  opacity: 0.4;
  animation: borderNeonPulse 2s ease-in-out infinite;
}

.overdrive-active .kpi-panel {
  position: relative;
  overflow: hidden;
}

.overdrive-active .kpi-panel::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0, 255, 255, 0.02) 0px,
    rgba(0, 255, 255, 0.02) 1px,
    transparent 1px,
    transparent 4px
  );
  z-index: 0;
  animation: scanlineScroll 0.15s linear infinite;
}

.overdrive-active .node-wrapper::after {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: inherit;
  border: 1px solid rgba(0, 255, 255, 0.25);
  pointer-events: none;
  animation: borderNeonPulse 2.5s ease-in-out infinite;
}

.overdrive-active .node-wrapper {
