    opacity: 0.9;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.5);
  }
}

@keyframes nodeNeonFlicker {
  0%, 100% {
    filter: drop-shadow(0 0 8px var(--color-primary)) drop-shadow(0 0 20px var(--color-primary));
