/* ============================================================
   MÉTRICAS DORA — Items
   ============================================================ */
.dora-metrics {
  display: flex;
  align-items: center;
  gap: 0;
  flex: 1;
  height: 100%;
}

.dora-metric {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
  height: 100%;
  padding: 0 12px;
  position: relative;
  min-width: 0;
}

/* Separador vertical entre métricas */
.dora-metric + .dora-metric::before {
  content: '';
  position: absolute;
  left: 0;
  top: 20%;
  height: 60%;
  width: 1px;
  background: rgba(var(--color-border-rgb, 80, 120, 200), 0.25);
}

.dora-metric__label {
  font-size: 9px;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 1.8px;
  color: var(--color-text-secondary, #7a8aaa);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  line-height: 1.2;
  margin-bottom: 2px;
}

.dora-metric__value {
  font-size: 16px;
  font-weight: 700;
  color: var(--color-accent-primary, #00d4ff);
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
  transition: color 0.3s ease;
  white-space: nowrap;
}

.dora-metric__unit {
  font-size: 9px;
  font-weight: 400;
  color: var(--color-text-secondary, #7a8aaa);
  letter-spacing: 0.5px;
  margin-top: 1px;
  line-height: 1;
}

/* Indicador de nivel DORA (elite / high / medium / low) */
.dora-metric__badge {
  display: inline-block;
  font-size: 8px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 1px 5px;
  border-radius: 2px;
  margin-top: 2px;
  line-height: 1.4;
}

.dora-metric__badge--elite {
  background: rgba(var(--color-accent-primary-rgb, 0, 212, 255), 0.15);
  color: var(--color-accent-primary, #00d4ff);
  border: 1px solid rgba(var(--color-accent-primary-rgb, 0, 212, 255), 0.4);
}

.dora-metric__badge--high {
  background: rgba(80, 200, 120, 0.12);
  color: #50c878;
  border: 1px solid rgba(80, 200, 120, 0.35);
}

.dora-metric__badge--medium {
  background: rgba(255, 180, 50, 0.12);
  color: #ffb432;
  border: 1px solid rgba(255, 180, 50, 0.35);
}

.dora-metric__badge--low {
  background: rgba(255, 80, 80, 0.12);
  color: #ff5050;
  border: 1px solid rgba(255, 80, 80, 0.35);
}

/* ============================================================
   SECCIÓN DE TRAZABILIDAD EN DORA BAR
   ============================================================ */
.dora-traceability {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-left: 16px;
  border-left: 1px solid rgba(var(--color-border-rgb, 80, 120, 200), 0.25);
  flex-shrink: 0;
}

.dora-traceability__label {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--color-text-secondary, #7a8aaa);
  white-space: nowrap;
}

.dora-traceability__value {
  font-size: 14px;
  font-weight: 700;
  color: var(--color-accent-primary, #00d4ff);
  font-variant-numeric: tabular-nums;
  transition: color 0.3s ease;
}

.dora-traceability__bar {
  width: 80px;
  height: 4px;
  background: rgba(var(--color-bg-dark-rgb, 5, 8, 18), 0.6);
  border-radius: 2px;
  overflow: hidden;
  flex-shrink: 0;
}

.dora-traceability__bar-fill {
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(
    90deg,
    var(--color-accent-secondary, #0066ff) 0%,
    var(--color-accent-primary, #00d4ff) 100%
  );
  box-shadow: 0 0 6px rgba(var(--color-accent-primary-rgb, 0, 212, 255), 0.55);
  transition: width 0.6s ease-out;
  will-change: width;
}

/* ============================================================
   ESTADOS OVERDRIVE — Modificadores aplicados via JS
   ============================================================ */

/* Paneles en modo Overdrive */
.overdrive-active .kpi-panel {
  border-color: rgba(var(--color-overdrive-rgb, 0, 255, 200), 0.35);
  background: rgba(var(--color-bg-panel-rgb, 10, 14, 26), 0.82);
}

.overdrive-active .kpi-item__value,
.overdrive-active .kpi-value {
  color: var(--color-overdrive, #00ffc8);
}

.overdrive-active .kpi-bar__fill {
  background: linear-gradient(
    90deg,
    var(--color-overdrive-secondary, #00aaff) 0%,
    var(--color-overdrive, #00ffc8) 100%
  );
  box-shadow: 0 2px 12px rgba(var(--color-overdrive-rgb, 0, 255, 200), 0.75);
}

.overdrive-active .speedometer-widget__value {
  color: var(--color-overdrive, #00ffc8);
}

.overdrive-active .dora-bar {
  border-top-color: rgba(var(--color-overdrive-rgb, 0, 255, 200), 0.4);
}

.overdrive-active .dora-metric__value {
  color: var(--color-overdrive, #00ffc8);
}

.overdrive-active .dora-traceability__value {
  color: var(--color-overdrive, #00ffc8);
}

.overdrive-active .dora-traceability__bar-fill {
  background: linear-gradient(
    90deg,
    var(--color-overdrive-secondary, #00aaff) 0%,
    var(--color-overdrive, #00ffc8) 100%
  );
  box-shadow: 0 0 8px rgba(var(--color-overdrive-rgb, 0, 255, 200), 0.7);
}

/* ============================================================
   RESPONSIVE — Ajustes para viewports reducidos
   ============================================================ */
@media (max-width: 1400px) {
  .kpi-panel {
    width: 260px;
  }

  .speedometer-widget__canvas {
    width: 180px;
    height: 108px;
  }

  .radar-widget__canvas {
    width: 180px;
    height: 180px;
  }
}

@media (max-width: 1200px) {
  .kpi-panel {
    width: 240px;
  }

  .speedometer-widget__value {
    font-size: 26px;
  }

  .dora-metric__value {
    font-size: 14px;
  }

  .dora-metric__label {
    font-size: 8px;
    letter-spacing: 1.2px;
  }
}

@media (max-width: 1024px) {
  .kpi-panel {
    width: 220px;
  }

  .kpi-list {
    padding: 12px 14px;
    gap: 10px;
  }

  .dora-traceability {
    display: none;
  }
}
